dashboard.definition:
{
  "title": "Compte bris de glace (secadm)",
  "description": "Vue centralisée de chaque modification et de chaque utilisation du ou des comptes bris de glace listés dans adx_breakglass_accounts.csv, construite à partir des événements de sécurité Windows collectés sur les contrôleurs de domaine (4624/4625, 4723/4724, 4738, 4722/4725, 4740/4767, 4728/4732/4756, 5136, 4672, 4648, 4768/4769/4771). Toute tuile rouge non nulle mérite d'être rapprochée d'un ticket d'incident.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Période",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@h,now"
      }
    }
  },
  "defaults": {},
  "visualizations": {
    "viz_1": {
      "type": "splunk.table",
      "title": "État du compte bris de glace (lookup AD)",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {
        "count": 5,
        "wrap": true,
        "columnFormat": {
          "Statut": {
            "rowBackgroundColors": "> table | seriesByName(\"Statut\") | matchValue(col0ColorConfig)"
          },
          "Verrouillé": {
            "rowBackgroundColors": "> table | seriesByName(\"Verrouillé\") | matchValue(col1ColorConfig)"
          }
        }
      },
      "description": "Les comptes bris de glace sont listés dans lookups/adx_breakglass_accounts.csv. État normal : ACTIF/DÉSACTIVÉ selon votre politique, mot de passe renouvelé après chaque usage, jamais utilisé hors incident. lastLogonTimestamp n'est répliqué que tous les ~9 à 14 jours : utilisez les panneaux d'événements ci-dessous pour l'usage en temps réel.",
      "context": {
        "col0ColorConfig": [
          {
            "match": "DÉSACTIVÉ",
            "value": "#65A637"
          },
          {
            "match": "ACTIF",
            "value": "#F8BE34"
          }
        ],
        "col1ColorConfig": [
          {
            "match": "VERROUILLÉ",
            "value": "#B0413E"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` `adx_risk` | where sam=\"$row.Compte.value$\" | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pso_name max_age_eff pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pso_name as \"PSO appliquée\", max_age_eff as \"Âge max du mot de passe (j)\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "title": "Jours depuis la dernière connexion (sur 90 j)",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | stats max(_time) as t | eval days=if(isnull(t),\"aucune sur 90 j\",floor((now()-t)/86400)) | fields days",
            "earliest": "-90d@d",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "title": "Jours depuis le dernier changement/reset du mot de passe (sur 1 an)",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search (event_id=4723 OR event_id=4724 OR event_id=4794) tgt_bg=* | stats max(_time) as t | eval days=if(isnull(t),\"aucun sur 1 an\",floor((now()-t)/86400)) | fields days",
            "earliest": "-365d@d",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "title": "Âge du mot de passe d'après le lookup AD (jours)",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | lookup adx_breakglass_accounts account AS sam OUTPUT label | where isnotnull(label) `adx_risk` | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pso_name max_age_eff pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pso_name as \"PSO appliquée\", max_age_eff as \"Âge max du mot de passe (j)\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "title": "Connexions depuis la dernière définition du mot de passe (90 j)",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | eval kind=\"logon\" | append [| `adx_users` | lookup adx_breakglass_accounts account AS sam OUTPUT label | where isnotnull(label) | stats max(pwd_last_set) as pls | eval _time=pls, kind=\"pwd\"] | eventstats max(eval(if(kind=\"pwd\",_time,null()))) as pls | where kind=\"logon\" AND _time>pls `adx_risk` | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \"), auto=mvjoin(auto_covered,\" | \") | table sam display_name upn etat risk_level risk_score raisons auto restantes review_progress review_basis department description location ou pso_name max_age_eff pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", auto as \"Raisons couvertes automatiquement\", restantes as \"Raisons restantes à traiter\", review_basis as \"Base de la revue\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pso_name as \"PSO appliquée\", max_age_eff as \"Âge max du mot de passe (j)\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-90d@d",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "title": "Connexions réussies",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#5385ce",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | table _time action event_id target_user actor_user src_ip src_host dc",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_7": {
      "type": "splunk.singlevalue",
      "title": "Connexions échouées",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search (event_id=4625 OR event_id=4771) tgt_bg=* | table _time action event_id target_user actor_user src_ip src_host dc",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_8": {
      "type": "splunk.singlevalue",
      "title": "Changements / resets de mot de passe",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search (event_id=4723 OR event_id=4724 OR event_id=4794) tgt_bg=* | table _time action event_id target_user actor_user src_ip src_host dc",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_9": {
      "type": "splunk.singlevalue",
      "title": "Modifications du compte",
      "dataSources": {
        "primary": "ds_9"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search (event_id=4738 OR event_id=4722 OR event_id=4725 OR event_id=4726 OR event_id=4781 OR event_id=4767 OR event_id=4740 OR event_id=5136) tgt_bg=* | table _time action event_id target_user actor_user src_ip src_host dc",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_10": {
      "type": "splunk.singlevalue",
      "title": "Changements d'appartenance aux groupes",
      "dataSources": {
        "primary": "ds_10"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search is_group_event=1 tgt_bg=* | table _time action event_id target_user actor_user src_ip src_host dc",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_11": {
      "type": "splunk.singlevalue",
      "title": "Actions effectuées PAR le compte",
      "dataSources": {
        "primary": "ds_11"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search act_bg=* (category=\"Account Management\" OR category=\"Group Management\" OR category=\"Directory Service Changes\") | table _time action event_id target_user actor_user src_ip src_host dc",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_12": {
      "type": "splunk.singlevalue",
      "title": "Connexions hors horaires",
      "dataSources": {
        "primary": "ds_12"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | `adx_offhours_filter` | table _time action event_id target_user actor_user src_ip src_host dc",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_13": {
      "type": "splunk.column",
      "title": "Activité du compte bris de glace dans le temps (par action)",
      "dataSources": {
        "primary": "ds_13"
      },
      "options": {
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | timechart count by action",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_14": {
      "type": "splunk.table",
      "title": "Journal des changements : qui a modifié le compte, quand, depuis où",
      "dataSources": {
        "primary": "ds_14"
      },
      "options": {
        "count": 10,
        "wrap": true,
        "columnFormat": {
          "Action": {
            "rowBackgroundColors": "> table | seriesByName(\"Action\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "context": {
        "col0ColorConfig": [
          {
            "match": "Réinitialisation de mot de passe (par un admin)",
            "value": "#B0413E"
          },
          {
            "match": "Changement de mot de passe (par le titulaire)",
            "value": "#F8BE34"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search tgt_bg=* (category=\"Account Management\" OR category=\"Group Management\" OR category=\"Directory Service Changes\") | eval changed_by=actor_user, group=group_name, object_attribute=if(event_id=\"5136\", AttributeLDAPDisplayName.\" = \".coalesce(AttributeValue,\"\"), null()) | sort - _time | table _time action target_user changed_by group object_attribute src_host src_ip dc event_id | rename _time as \"Heure\", action as \"Action\", target_user as \"Compte cible\", changed_by as \"Modifié par\", group as \"Groupe\", object_attribute as \"Attribut modifié\", src_host as \"Hôte source\", src_ip as \"IP source\", dc as \"DC\", event_id as \"ID événement\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_15": {
      "type": "splunk.table",
      "title": "Utilisation du compte : connexions",
      "dataSources": {
        "primary": "ds_15"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | lookup adx_logon_types logon_type OUTPUT logon_type_label | eval auth_package=coalesce(AuthenticationPackageName, Authentication_Package), process=coalesce(LogonProcessName, Logon_Process) | sort - _time | table _time target_user logon_type_label src_ip src_host dc auth_package process | rename _time as \"Heure\", target_user as \"Compte cible\", logon_type_label as \"Type de session\", src_ip as \"IP source\", src_host as \"Hôte source\", dc as \"DC\", auth_package as \"Package d'authentification\", process as \"Processus\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_16": {
      "type": "splunk.table",
      "title": "Tentatives échouées",
      "dataSources": {
        "primary": "ds_16"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search (event_id=4625 OR event_id=4771) tgt_bg=* | eval code=coalesce(Sub_Status, SubStatus, Failure_Code, Status) | lookup adx_failure_codes code OUTPUT reason | sort - _time | table _time action target_user reason code src_ip src_host dc | rename _time as \"Heure\", action as \"Action\", target_user as \"Compte cible\", reason as \"Raison\", code as \"Code\", src_ip as \"IP source\", src_host as \"Hôte source\", dc as \"DC\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_17": {
      "type": "splunk.table",
      "title": "Actions effectuées PAR le compte bris de glace",
      "dataSources": {
        "primary": "ds_17"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search act_bg=* (category=\"Account Management\" OR category=\"Group Management\" OR category=\"Directory Service Changes\") | eval affected_object=coalesce(group_name.\" <- \".target_user, target_user) | sort - _time | table _time action actor_user affected_object src_host src_ip dc | rename _time as \"Heure\", action as \"Action\", actor_user as \"Acteur\", affected_object as \"Objet concerné\", src_host as \"Hôte source\", src_ip as \"IP source\", dc as \"DC\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_18": {
      "type": "splunk.table",
      "title": "Sessions privilégiées et usage d'identifiants explicites",
      "dataSources": {
        "primary": "ds_18"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search (event_id=4672 OR event_id=4648) | eval privileges=coalesce(PrivilegeList, Privileges) | sort - _time | table _time action target_user actor_user src_host dc privileges | rename _time as \"Heure\", action as \"Action\", target_user as \"Compte cible\", actor_user as \"Acteur\", src_host as \"Hôte source\", dc as \"DC\", privileges as \"Privilèges\"",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_19": {
      "type": "splunk.bar",
      "title": "Utilisation par hôte / IP source",
      "dataSources": {
