          "options": {
            "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | eval source=coalesce(src_host, src_ip, \"local / inconnu\") | stats count by source | sort - count | head 15",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_20": {
      "type": "splunk.pie",
      "title": "Qui modifie le compte (acteurs)",
      "dataSources": {
        "primary": "ds_20"
      },
      "options": {
        "legendDisplay": "bottom"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search tgt_bg=* (category=\"Account Management\" OR category=\"Group Management\") | stats count by actor_user | sort - count",
            "earliest": "$global_time.earliest$",
