    "viz_22": {
      "type": "splunk.table",
      "title": "Hôtes sources vus pour la première fois (7 derniers jours vs référence de 90 jours)",
      "dataSources": {
        "primary": "ds_22"
      },
      "options": {
        "count": 8,
        "wrap": true
      },
      "description": "Fenêtre fixe de 90 jours, indépendante du sélecteur de période.",
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | eval source=coalesce(src_host, src_ip, \"local / inconnu\") | stats min(_time) as first_seen, max(_time) as last_seen, count by source | where first_seen>relative_time(now(),\"-7d\") | eval first_seen=strftime(first_seen,\"%Y-%m-%d %H:%M\"), last_seen=strftime(last_seen,\"%Y-%m-%d %H:%M\") | table source first_seen last_seen count | rename source as \"Source\", first_seen as \"Première vue\", last_seen as \"Dernière vue\", count as \"Nombre\"",
            "earliest": "-90d@d",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_23": {
      "type": "splunk.table",
      "title": "Configuration des comptes bris de glace (lookup)",
      "dataSources": {
        "primary": "ds_23"
      },
      "options": {
        "count": 5,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| inputlookup adx_breakglass_accounts.csv | table account label owner notes | rename account as \"Compte\", label as \"Libellé\", owner as \"Propriétaire\", notes as \"Notes\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "État du compte bris de glace (lookup AD)",
      "options": {
        "query": "| `adx_users` | lookup adx_breakglass_accounts account AS sam OUTPUT label | where isnotnull(label) | eval status=if(is_disabled=1,\"DÉSACTIVÉ\",\"ACTIF\"), locked=if(is_locked=1,\"VERROUILLÉ\",\"non\"), never_expires=if(pwd_never_expires=1,\"OUI\",\"non\"), pwd_last_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), last_logon_replicated=strftime(last_logon,\"%Y-%m-%d %H:%M\"), privileged=if(is_privileged=1,\"OUI\",\"non\") | table sam status locked pwd_last_set pwd_age_days never_expires last_logon_replicated privileged priv_groups | rename sam as \"Compte\", status as \"Statut\", locked as \"Verrouillé\", pwd_last_set as \"MdP défini le\", pwd_age_days as \"Âge du mot de passe (j)\", never_expires as \"MdP sans expiration\", last_logon_replicated as \"Dernière connexion (répliquée)\", privileged as \"Privilégié\", priv_groups as \"Groupes privilégiés\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Jours depuis la dernière connexion (sur 90 j)",
      "options": {
        "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | stats max(_time) as t | eval days=if(isnull(t),\"aucune sur 90 j\",floor((now()-t)/86400)) | fields days",
        "queryParameters": {
          "earliest": "-90d@d",
          "latest": "now"
        }
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Jours depuis le dernier changement/reset du mot de passe (sur 1 an)",
      "options": {
        "query": "`adx_breakglass_events` | search (event_id=4723 OR event_id=4724 OR event_id=4794) tgt_bg=* | stats max(_time) as t | eval days=if(isnull(t),\"aucun sur 1 an\",floor((now()-t)/86400)) | fields days",
        "queryParameters": {
          "earliest": "-365d@d",
          "latest": "now"
        }
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Âge du mot de passe d'après le lookup AD (jours)",
      "options": {
        "query": "| `adx_users` | lookup adx_breakglass_accounts account AS sam OUTPUT label | where isnotnull(label) | stats max(pwd_age_days) as days",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Connexions depuis la dernière définition du mot de passe (90 j)",
      "options": {
        "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | eval kind=\"logon\" | append [| `adx_users` | lookup adx_breakglass_accounts account AS sam OUTPUT label | where isnotnull(label) | stats max(pwd_last_set) as pls | eval _time=pls, kind=\"pwd\"] | eventstats max(eval(if(kind=\"pwd\",_time,null()))) as pls | where kind=\"logon\" AND _time>pls | stats count",
        "queryParameters": {
          "earliest": "-90d@d",
          "latest": "now"
        }
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Connexions réussies",
      "options": {
        "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Connexions échouées",
      "options": {
        "query": "`adx_breakglass_events` | search (event_id=4625 OR event_id=4771) tgt_bg=* | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Changements / resets de mot de passe",
      "options": {
        "query": "`adx_breakglass_events` | search (event_id=4723 OR event_id=4724 OR event_id=4794) tgt_bg=* | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Modifications du compte",
      "options": {
        "query": "`adx_breakglass_events` | search (event_id=4738 OR event_id=4722 OR event_id=4725 OR event_id=4726 OR event_id=4781 OR event_id=4767 OR event_id=4740 OR event_id=5136) tgt_bg=* | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "Changements d'appartenance aux groupes",
      "options": {
        "query": "`adx_breakglass_events` | search is_group_event=1 tgt_bg=* | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "Actions effectuées PAR le compte",
      "options": {
        "query": "`adx_breakglass_events` | search act_bg=* (category=\"Account Management\" OR category=\"Group Management\" OR category=\"Directory Service Changes\") | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "Connexions hors horaires",
      "options": {
        "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | `adx_offhours_filter` | stats count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_13": {
      "type": "ds.search",
      "name": "Activité du compte bris de glace dans le temps (par action)",
      "options": {
        "query": "`adx_breakglass_events` | timechart count by action",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_14": {
      "type": "ds.search",
      "name": "Journal des changements : qui a modifié le compte, quand, depuis où",
      "options": {
        "query": "`adx_breakglass_events` | search tgt_bg=* (category=\"Account Management\" OR category=\"Group Management\" OR category=\"Directory Service Changes\") | eval changed_by=actor_user, group=group_name, object_attribute=if(event_id=\"5136\", AttributeLDAPDisplayName.\" = \".coalesce(AttributeValue,\"\"), null()) | sort - _time | table _time action target_user changed_by group object_attribute src_host src_ip dc event_id | rename _time as \"Heure\", action as \"Action\", target_user as \"Compte cible\", changed_by as \"Modifié par\", group as \"Groupe\", object_attribute as \"Attribut modifié\", src_host as \"Hôte source\", src_ip as \"IP source\", dc as \"DC\", event_id as \"ID événement\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_15": {
      "type": "ds.search",
      "name": "Utilisation du compte : connexions",
      "options": {
        "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | lookup adx_logon_types logon_type OUTPUT logon_type_label | eval auth_package=coalesce(AuthenticationPackageName, Authentication_Package), process=coalesce(LogonProcessName, Logon_Process) | sort - _time | table _time target_user logon_type_label src_ip src_host dc auth_package process | rename _time as \"Heure\", target_user as \"Compte cible\", logon_type_label as \"Type de session\", src_ip as \"IP source\", src_host as \"Hôte source\", dc as \"DC\", auth_package as \"Package d'authentification\", process as \"Processus\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_16": {
      "type": "ds.search",
      "name": "Tentatives échouées",
      "options": {
        "query": "`adx_breakglass_events` | search (event_id=4625 OR event_id=4771) tgt_bg=* | eval code=coalesce(Sub_Status, SubStatus, Failure_Code, Status) | lookup adx_failure_codes code OUTPUT reason | sort - _time | table _time action target_user reason code src_ip src_host dc | rename _time as \"Heure\", action as \"Action\", target_user as \"Compte cible\", reason as \"Raison\", code as \"Code\", src_ip as \"IP source\", src_host as \"Hôte source\", dc as \"DC\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_17": {
      "type": "ds.search",
      "name": "Actions effectuées PAR le compte bris de glace",
      "options": {
        "query": "`adx_breakglass_events` | search act_bg=* (category=\"Account Management\" OR category=\"Group Management\" OR category=\"Directory Service Changes\") | eval affected_object=coalesce(group_name.\" <- \".target_user, target_user) | sort - _time | table _time action actor_user affected_object src_host src_ip dc | rename _time as \"Heure\", action as \"Action\", actor_user as \"Acteur\", affected_object as \"Objet concerné\", src_host as \"Hôte source\", src_ip as \"IP source\", dc as \"DC\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_18": {
      "type": "ds.search",
      "name": "Sessions privilégiées et usage d'identifiants explicites",
      "options": {
        "query": "`adx_breakglass_events` | search (event_id=4672 OR event_id=4648) | eval privileges=coalesce(PrivilegeList, Privileges) | sort - _time | table _time action target_user actor_user src_host dc privileges | rename _time as \"Heure\", action as \"Action\", target_user as \"Compte cible\", actor_user as \"Acteur\", src_host as \"Hôte source\", dc as \"DC\", privileges as \"Privilèges\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_19": {
      "type": "ds.search",
      "name": "Utilisation par hôte / IP source",
      "options": {
        "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | eval source=coalesce(src_host, src_ip, \"local / inconnu\") | stats count by source | sort - count | head 15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_20": {
      "type": "ds.search",
      "name": "Qui modifie le compte (acteurs)",
      "options": {
        "query": "`adx_breakglass_events` | search tgt_bg=* (category=\"Account Management\" OR category=\"Group Management\") | stats count by actor_user | sort - count",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_21": {
      "type": "ds.search",
      "name": "Connexions par heure de la journée",
      "options": {
        "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | eval hour=strftime(_time,\"%H\") | stats count by hour | sort hour",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_22": {
      "type": "ds.search",
      "name": "Hôtes sources vus pour la première fois (7 derniers jours vs référence de 90 jours)",
      "options": {
        "query": "`adx_breakglass_events` | search event_id=4624 tgt_bg=* | eval source=coalesce(src_host, src_ip, \"local / inconnu\") | stats min(_time) as first_seen, max(_time) as last_seen, count by source | where first_seen>relative_time(now(),\"-7d\") | eval first_seen=strftime(first_seen,\"%Y-%m-%d %H:%M\"), last_seen=strftime(last_seen,\"%Y-%m-%d %H:%M\") | table source first_seen last_seen count | rename source as \"Source\", first_seen as \"Première vue\", last_seen as \"Dernière vue\", count as \"Nombre\"",
        "queryParameters": {
          "earliest": "-90d@d",
          "latest": "now"
        }
      }
    },
    "ds_23": {
      "type": "ds.search",
      "name": "Configuration des comptes bris de glace (lookup)",
      "options": {
        "query": "| inputlookup adx_breakglass_accounts.csv | table account label owner notes | rename account as \"Compte\", label as \"Libellé\", owner as \"Propriétaire\", notes as \"Notes\"",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    }
